function currentConversationalTask(message, interpretation = {}) {
  const task = interpretation.current_task;
  if (interpretation.interpretation_valid === false || !task ||
      !['draft', 'transform', 'summarize', 'show'].includes(task.operation) ||
      typeof task.request !== 'string' || task.request.trim().length < 5 ||
      !String(message || '').includes(task.request.trim())) return null;
  return {operation: task.operation, request: task.request.trim()};
}
function hasExplicitCurrentReminderRequest(message) {
  const text = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (/\bno\s+(?:(?:me|quiero|necesito|que)\s+)*(?:recuerd\w*|record\w*|avis\w*)/.test(text)) return false;
  return /\b(?:recuerdame|recordarme|me (?:puedes |podrias |podrian |pueden )?recordar)\b/.test(text) ||
    /\b(?:avisame|me (?:puedes |podrias )?avisar)\b.{0,45}\b(?:manana|pasado manana|lunes|martes|miercoles|jueves|viernes|sabado|domingo|en \w+ (?:dias|semanas)|el \d+)\b/.test(text) &&
    !/\b(?:listo|disponible|generad[oa])\b/.test(text);
}
const allowedSignals = ["information_request","broad_information_request","positive_interest","question","objection_price","objection_trust","objection_timing","deferred_interest","explicit_purchase","contextual_affirmation","ambiguous_acknowledgement","gratitude","rejection","ai_value_objection","support_issue","other"];
const allowedTopics = ["payment_methods","payment_security","price","start_date","refund","health_scope","allergies","privacy","what_is_included","how_it_works","fulfillment_timing","fulfillment_notification","post_purchase","personalization","diet_support","product_scope","business_location","portal","WhatsApp_assistance","AI","ai_value_objection","human_preference","credentials","professional_responsibility","trust"];
try {
  const raw = String($input.first().json.output || '').replace(/^```(?:json)?\s*|\s*```$/g, '');
  const parsed = JSON.parse(raw);
  return [{ json: {
    interpretation_valid: allowedSignals.includes(parsed.buyer_signal),
    buyer_signal: allowedSignals.includes(parsed.buyer_signal) ? parsed.buyer_signal : 'other',
    topic: allowedTopics.includes(parsed.topic) ? parsed.topic : null,
    goal: typeof parsed.goal === 'string' ? parsed.goal.slice(0, 160) : null,
    current_task: currentConversationalTask($('Set Session Id').item.json.chatInput, parsed),
    goal_supplied: parsed.goal_supplied === true,
    timing_iso: typeof parsed.timing_iso === 'string' ? parsed.timing_iso : null,
    explicit_reminder_request: parsed.explicit_reminder_request === true && hasExplicitCurrentReminderRequest($('Set Session Id').item.json.chatInput),
    material_question: parsed.material_question === true,
    substantive_engagement: parsed.substantive_engagement !== false,
    needs_clarification: parsed.needs_clarification === true
  } }];
} catch {
  return [{ json: { interpretation_valid: false, buyer_signal: 'other', topic: null, goal: null, goal_supplied: false, timing_iso: null, explicit_reminder_request: false, material_question: false, substantive_engagement: false, needs_clarification: true } }];
}

